#!/usr/bin/env python3
"""Draws the flat SVG illustrations in public/img/money (original artwork for this project).
Run once: python3 scripts/draw-money-icons.py"""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / 'public' / 'img' / 'money'
OUT.mkdir(parents=True, exist_ok=True)

BG = lambda c: f'<rect width="64" height="64" rx="8" fill="{c}"/>'
COIN = lambda x, y, r=6: f'<circle cx="{x}" cy="{y}" r="{r}" fill="#ffd54a" stroke="#c9a227" stroke-width="1.5"/><text x="{x}" y="{y + r * .45}" font-family="sans-serif" font-size="{r * 1.2}" font-weight="bold" fill="#c9a227" text-anchor="middle">$</text>'
BILL = lambda x, y, w=28, h=14: f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="2" fill="#7cb342" stroke="#33691e"/><circle cx="{x + w / 2}" cy="{y + h / 2}" r="{h * .3}" fill="#c5e1a5" stroke="#33691e"/><text x="{x + 3}" y="{y + h - 3}" font-family="sans-serif" font-size="5" fill="#33691e">1</text>'
CARD = lambda x, y, c='#4d96ff': f'<rect x="{x}" y="{y}" width="30" height="19" rx="3" fill="{c}"/><rect x="{x}" y="{y + 5}" width="30" height="4" fill="#222"/><rect x="{x + 3}" y="{y + 12}" width="10" height="3" fill="#ffd54a"/><rect x="{x + 16}" y="{y + 12}" width="10" height="2" fill="#fff"/>'
PERSON = lambda x, y, shirt='#e63946', skin='#f5c6a5': f'<circle cx="{x}" cy="{y}" r="5" fill="{skin}"/><path d="M{x - 5} {y - 1} Q{x} {y - 8} {x + 5} {y - 1}" fill="#5a2d1a"/><rect x="{x - 6}" y="{y + 5}" width="12" height="14" rx="3" fill="{shirt}"/>'
ARROW = lambda x1, y1, x2, y2, c='#222': f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{c}" stroke-width="2.5"/><circle cx="{x2}" cy="{y2}" r="2.5" fill="{c}"/>'
SCREEN = lambda body: f'<rect x="6" y="8" width="52" height="38" rx="3" fill="#222"/><rect x="9" y="11" width="46" height="32" fill="#fff"/><rect x="24" y="46" width="16" height="4" fill="#555"/><rect x="18" y="50" width="28" height="3" rx="1" fill="#999"/>{body}'

ICONS = {
    'credit-card': BG('#e3f2fd') + CARD(10, 14, '#4d96ff') + CARD(22, 28, '#e63946'),
    'wealthy': BG('#fff8e1') + PERSON(32, 16, '#222') + '<rect x="24" y="4" width="16" height="6" fill="#222"/><rect x="22" y="9" width="20" height="2" fill="#222"/>' + COIN(12, 44, 7) + COIN(24, 50, 7) + COIN(40, 50, 7) + COIN(52, 44, 7) + BILL(18, 36, 28, 10),
    'broke': BG('#eceff1') + PERSON(32, 18, '#607d8b') + '<path d="M18 38 Q14 44 8 42" stroke="#f5c6a5" stroke-width="3" fill="none"/><path d="M46 38 Q50 44 56 42" stroke="#f5c6a5" stroke-width="3" fill="none"/><rect x="20" y="42" width="24" height="16" rx="2" fill="#8d5524"/><path d="M22 44 L42 44" stroke="#5a2d1a" stroke-width="2"/><text x="32" y="55" font-family="sans-serif" font-size="8" fill="#fff" text-anchor="middle">$0</text><path d="M29 17 L35 17" stroke="#222" stroke-width="1.5"/>',
    'coins': BG('#fffde7') + COIN(18, 42, 9) + COIN(38, 46, 9) + COIN(30, 26, 9) + COIN(50, 30, 7),
    'savings-account': BG('#e8f5e9') + '<ellipse cx="32" cy="38" rx="20" ry="14" fill="#ff8fa3"/><circle cx="50" cy="32" r="6" fill="#ff8fa3"/><circle cx="52" cy="31" r="1" fill="#222"/><rect x="18" y="50" width="4" height="6" fill="#e63946"/><rect x="42" y="50" width="4" height="6" fill="#e63946"/><rect x="26" y="22" width="12" height="3" rx="1" fill="#222"/>' + COIN(32, 14, 5),
    'cash': BG('#f1f8e9') + BILL(8, 30, 34, 16) + BILL(18, 20, 34, 16) + BILL(28, 10, 34, 16),
    'loan': BG('#e8eaf6') + '<rect x="4" y="16" width="24" height="30" rx="2" fill="#fff" stroke="#999"/><path d="M6 12 L16 6 L26 12Z" fill="#5c6bc0"/><rect x="8" y="22" width="16" height="2" fill="#999"/><rect x="8" y="27" width="16" height="2" fill="#999"/><rect x="8" y="32" width="10" height="2" fill="#999"/><text x="16" y="42" font-family="sans-serif" font-size="6" fill="#5c6bc0" text-anchor="middle">LOAN</text>' + ARROW(30, 28, 44, 28, '#4caf50') + BILL(40, 34, 20, 10) + PERSON(52, 16, '#4d96ff'),
    'mortgage': BG('#fff3e0') + '<rect x="14" y="26" width="36" height="28" fill="#c97b63"/><path d="M10 28 L32 10 L54 28Z" fill="#8d5524"/><rect x="28" y="40" width="8" height="14" fill="#5a2d1a"/><rect x="18" y="32" width="8" height="6" fill="#fff59d"/><rect x="38" y="32" width="8" height="6" fill="#fff59d"/>' + COIN(54, 50, 6) + '<text x="32" y="22" font-family="sans-serif" font-size="6" fill="#fff" text-anchor="middle">%</text>',
    'taxes': BG('#fce4ec') + '<rect x="14" y="8" width="36" height="48" rx="2" fill="#fff" stroke="#999"/><text x="32" y="22" font-family="sans-serif" font-size="9" font-weight="bold" fill="#c62828" text-anchor="middle">TAX</text><rect x="20" y="28" width="24" height="2" fill="#999"/><rect x="20" y="34" width="24" height="2" fill="#999"/><rect x="20" y="40" width="14" height="2" fill="#999"/><text x="40" y="52" font-family="sans-serif" font-size="8" fill="#c62828" text-anchor="middle">$</text>',
    'atm': BG('#e0f2f1') + '<rect x="14" y="4" width="36" height="56" rx="3" fill="#455a64"/><rect x="18" y="10" width="28" height="16" fill="#8ecae6"/><text x="32" y="21" font-family="sans-serif" font-size="8" font-weight="bold" fill="#222" text-anchor="middle">ATM</text>' + ''.join(f'<rect x="{20 + i * 8}" y="{30 + j * 6}" width="6" height="4" fill="#ccc"/>' for i in range(3) for j in range(2)) + '<rect x="18" y="46" width="28" height="3" fill="#222"/>' + BILL(20, 44, 24, 8),
    'save-up': BG('#e8f5e9') + '<rect x="10" y="30" width="44" height="24" rx="3" fill="#8d5524"/><rect x="10" y="26" width="44" height="6" fill="#5a2d1a"/><rect x="29" y="22" width="6" height="8" fill="#ffd54a"/>' + COIN(20, 42, 5) + COIN(32, 44, 5) + COIN(44, 42, 5) + ARROW(32, 4, 32, 18, '#4caf50') + '<text x="46" y="14" font-family="sans-serif" font-size="8" fill="#4caf50">+</text>',
    'waste-money': BG('#ffebee') + '<rect x="20" y="30" width="24" height="26" rx="3" fill="#607d8b"/><rect x="17" y="26" width="30" height="5" rx="2" fill="#455a64"/>' + BILL(24, 36, 16, 8) + COIN(30, 50, 4) + BILL(4, 10, 20, 10) + '<g transform="rotate(30 48 14)">' + BILL(38, 8, 20, 10) + '</g>' + ARROW(16, 20, 26, 28, '#c62828'),
    'borrow-lend': BG('#e3f2fd') + PERSON(14, 18, '#4d96ff') + PERSON(50, 18, '#e63946', '#c68642') + ARROW(22, 40, 42, 40, '#4caf50') + BILL(24, 30, 16, 8) + '<text x="14" y="52" font-family="sans-serif" font-size="6" fill="#222" text-anchor="middle">lend</text><text x="50" y="52" font-family="sans-serif" font-size="6" fill="#222" text-anchor="middle">borrow</text>',
    'in-stock': BG('#e8f5e9') + ''.join(f'<rect x="{8 + i * 17}" y="{20 + (i % 2) * 6}" width="14" height="14" rx="1" fill="#c97b63" stroke="#8d5524"/>' for i in range(3)) + '<rect x="4" y="40" width="56" height="4" fill="#8d5524"/><circle cx="50" cy="12" r="8" fill="#4caf50"/><path d="M45 12 L49 16 L56 8" stroke="#fff" stroke-width="2.5" fill="none"/>',
    'delivery': BG('#fff8e1') + '<rect x="4" y="22" width="34" height="22" fill="#ffd54a"/><rect x="38" y="30" width="18" height="14" fill="#ffd54a"/><rect x="40" y="32" width="10" height="6" fill="#8ecae6"/><circle cx="14" cy="46" r="5" fill="#222"/><circle cx="48" cy="46" r="5" fill="#222"/><rect x="10" y="26" width="14" height="12" fill="#c97b63"/><rect x="10" y="31" width="14" height="2" fill="#8d5524"/><path d="M0 34 L2 34" stroke="#222"/>',
    'checkout': BG('#e8eaf6') + SCREEN('<rect x="12" y="15" width="40" height="6" fill="#eee"/><rect x="12" y="24" width="24" height="4" fill="#ccc"/><rect x="12" y="30" width="18" height="4" fill="#ccc"/><rect x="30" y="36" width="22" height="6" rx="2" fill="#4caf50"/><text x="41" y="40.5" font-family="sans-serif" font-size="4.5" fill="#fff" text-anchor="middle">CHECKOUT</text>') + '<rect x="40" y="14" width="10" height="7" rx="1" fill="#4d96ff"/><path d="M42 14 L42 12 Q45 9 48 12 L48 14" stroke="#4d96ff" stroke-width="1.5" fill="none"/>',
    'cart': BG('#fff3e0') + '<path d="M8 14 L16 14 L22 40 L50 40 L56 20 L18 20" stroke="#333" stroke-width="3" fill="none" stroke-linejoin="round"/><circle cx="26" cy="48" r="4" fill="#333"/><circle cx="46" cy="48" r="4" fill="#333"/>' + ''.join(f'<rect x="{24 + i * 9}" y="{24 + i * 2}" width="7" height="{14 - i * 2}" fill="{c}"/>' for i, c in enumerate(['#e63946', '#4caf50', '#4d96ff'])),
    'item': BG('#f3e5f5') + '<rect x="14" y="16" width="36" height="36" rx="2" fill="#c97b63" stroke="#8d5524"/><rect x="14" y="30" width="36" height="6" fill="#ffd54a"/><rect x="29" y="16" width="6" height="36" fill="#ffd54a"/><rect x="40" y="8" width="16" height="10" rx="1" fill="#fff" stroke="#999"/><text x="48" y="15.5" font-family="sans-serif" font-size="6" fill="#222" text-anchor="middle">$420</text>',
}

for name, body in ICONS.items():
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64">{body}</svg>'
    (OUT / f'{name}.svg').write_text(svg)
print(f'wrote {len(ICONS)} icons to {OUT}')
